#include <vector>

int findSecondLargest(std::vector<int> arr) {
    if (arr.size() < 2) return -1; // No valid second largest

    int left = 0;
    int right = arr.size() - 1;

    while (left != right) {
        auto pivotIndex = partition(arr, left, right);

        if (pivotIndex == arr.size() - 2) { // Found the second largest
            return arr[pivotIndex];
        } else if (pivotIndex > arr.size() - 2) { // Need to search further in left part
            right = pivotIndex - 1;
        } else { // Need to search further in right part
            left = pivotIndex + 1;
        }
    }

    return -1; // Not enough elements to form a second largest
}

int partition(std::vector<int>& arr, int left, int right) {
    std::swap(arr[left], arr[right]); // Move pivot to end
    int i = left;
    for (int j = left; j < right; ++j) {
        if (arr[j] <= arr[right]) {
            std::swap(arr[i], arr[j]);
            i++;
        }
    }
    std::swap(arr[i], arr[right]); // Place pivot at correct position
    return i;
}

