const { getRegion } = require("aws-sdk/lib/config");

// Initialize the CloudFront client
const client = new CloudFrontClient({
    region: getRegion(),
});

async function waitForInvalidationCompletion(invalidationId) {
    let attempts = 0;
    const MAX_ATTEMPTS = 7;

    try {
        // Wait until the invalidation completes
        while (attempts < MAX_ATTEMPTS) {
            const response = await client.send(new CreateInvalidateCommand({
                Id: invalidationId,
                Force: true,
            }));

            console.log(`Operation completed after ${response.status} seconds.`);
            break; // Operation successful on first attempt
        }
    } catch (error) {
        if (error.response && error.response.statusCode === 404 || error.response.statusCode === 504) {
            console.error('Resource Not Ready:', error.message);
            return false;
        }

        if (error.response && error.response.statusCode >= 400) {
            console.error('Timeout Error:', error.message);
            return false;
        }

        throw error; // Rethrow other unexpected errors
    }

    return true;
}

